package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import net.minecraft.network.chat.Component;import net.minecraft.core.BlockPos;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;public class HydroacousticTubeBlock extends Block{public static final IntegerProperty MEDIUM=IntegerProperty.create("medium",0,2);public HydroacousticTubeBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(MEDIUM,0));}@Override public MapCodec<HydroacousticTubeBlock> codec(){return RedstoneEngineering.HYDROACOUSTIC_TUBE_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(MEDIUM);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int m=(s.getValue(MEDIUM)+1)%3;l.setBlock(p,s.setValue(MEDIUM,m),Block.UPDATE_CLIENTS);String n=m==0?"water":m==1?"milk-model":"lava";pl.displayClientMessage(Component.literal("Hydroacoustic medium="+n),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}